const stable = version => /^\d+\.\d+\.\d+(?:\+[^-]+)?$/.test(version ?? '');
const exact = version => /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/.test(version ?? '');

async function text(key) { assert.ok(await exists(pathOf(key)), `missing canonical v2 artifact: ${ARTIFACTS[key]}`); return readFile(pathOf(key)); }
