function obj(value, label) { assert.ok(value && typeof value === 'object' && !Array.isArray(value), `${label} must be an object`); return value; }
function keys(value, required, label) { obj(value,label); const missing=required.filter(k=>!Object.hasOwn(value,k)); assert.deepEqual(missing,[],`${label} missing: ${missing.join(', ')}`); }
function composite(row) { return [row.manifest_path,row.dependency_section,row.package_name,row.context].join(' + '); }
function canonical(value) { if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`; if (value && typeof value==='object') return `{${Object.keys(value).sort().map(k=>`${JSON.stringify(k)}:${canonical(value[k])}`).join(',')}}`; return JSON.stringify(value); }
function without(value, field) { const copy=structuredClone(value); delete copy[field]; return copy; }
