function parseRegistry(source) {
  const lines=source.toString('utf8').trim().split('\n').filter(Boolean);
  assert.ok(lines.length>1,'registry snapshot must contain header and records');
  const parsed=lines.map((line,i)=>{try{return JSON.parse(line)}catch(e){assert.fail(`registry JSONL line ${i+1}: ${e.message}`)}});
  const [header,...records]=parsed; assert.equal(header.type,'header'); keys(header,['t0','registry_base_url','response_family_digest','credential_input'], 'registry header');
  assert.ok(utc(header.t0)); assert.equal(header.registry_base_url,'https://registry.npmjs.org'); assert.equal(header.credential_input,false);
  assert.deepEqual(records.map(r=>r.package_name),[...records.map(r=>r.package_name)].sort(),'registry records must be sorted');
  assert.equal(new Set(records.map(r=>r.package_name)).size,records.length,'duplicate registry record');
  assert.deepEqual(new Set(records.map(r=>r.package_name)),new Set(PACKAGE_NAMES),'registry package inventory differs');
  for(const r of records){keys(r,['type','package_name','dist_tags','response_digest','retrieved_at','versions'],'registry record'); assert.equal(r.type,'registry_package'); assert.ok(fullSha(r.response_digest)); assert.ok(utc(r.retrieved_at)); assert.ok(Array.isArray(r.versions)&&r.versions.length); for(const v of r.versions){keys(v,['version','published_at','deprecated','engines','peers','integrity','tags'],'registry version'); assert.ok(utc(v.published_at)); assert.ok(v.published_at<=header.t0,'T0-ineligible version'); assert.match(v.integrity,/^sha512-/);}}
  return {header,records,byName:new Map(records.map(r=>[r.package_name,r]))};
}

function versionRecord(registry,name,version){const record=registry.byName.get(name); assert.ok(record,`orphan declaration registry record: ${name}`); const found=record.versions.find(v=>v.version===version); assert.ok(found,`selected version absent from index: ${name}@${version}`); return {record,found};}
function validateException(row,registry){keys(row,['exception','maintenance_owner','review'],'exception row'); const e=row.exception; keys(e,['rejected_latest','rejected_latest_integrity','higher_eligible_candidates','constraint_or_failure','commands','transcript_digests','highest_compatible_proof'],'compatibility exception'); assert.equal(row.maintenance_owner,'Ryan Lisse'); assert.match(row.review,/architect.*approve.*critic.*approve/i); const {record}=versionRecord(registry,row.package_name,row.selected_version); assert.equal(e.rejected_latest,record.dist_tags.latest); assert.match(e.rejected_latest_integrity,/^sha512-/); const higher=record.versions.filter(v=>stable(v.version)&&v.version!==row.selected_version&&v.published_at<=registry.header.t0&&v.version!==undefined).filter(v=>e.higher_eligible_candidates.some(c=>c.version===v.version)); assert.ok(e.higher_eligible_candidates.length>0,'exception omits higher candidates'); assert.equal(higher.length,e.higher_eligible_candidates.length,'unexamined higher candidate'); for(const c of e.higher_eligible_candidates) keys(c,['version','rejection_proof','evidence_digest'],'higher candidate'); assert.equal(e.highest_compatible_proof,true);}

function validateResolution(r,registry){
  keys(r,['schema_version','resolver_policy_version','t0','snapshot_family_id','parent_snapshot_id','registry_base_url','registry_snapshot_sha256','node_release_snapshot_sha256','manifest_allowlist','declarations','retry_history','seal_time','snapshot_id'],'latest resolution');
  assert.equal(r.schema_version,2); assert.ok(utc(r.t0)&&utc(r.seal_time)); assert.equal(r.t0,registry.header.t0); assert.equal(r.registry_base_url,'https://registry.npmjs.org'); assert.ok(fullSha(r.snapshot_id)); assert.ok(fullSha(r.registry_snapshot_sha256)); assert.ok(fullSha(r.node_release_snapshot_sha256));
  assert.equal(r.snapshot_id,`sha256:${sha(canonical(without(r,'snapshot_id')))}`,'snapshot ID/JCS mismatch');
  assert.ok(Array.isArray(r.declarations)); const ids=r.declarations.map(composite); assert.equal(new Set(ids).size,ids.length,'duplicate declaration composite key');
  for(const row of r.declarations){keys(row,['manifest_path','dependency_section','package_name','context','selected_version','status','registry_record'],'declaration row'); assert.equal(row.registry_record,row.package_name); assert.ok(exact(row.selected_version),'floating or invalid version'); assert.ok(['exact_latest','compatibility_exception','prerelease_only_exception'].includes(row.status)); const {record,found}=versionRecord(registry,row.package_name,row.selected_version); if(row.status==='exact_latest'){assert.ok(stable(row.selected_version)); assert.equal(row.selected_version,record.dist_tags.latest,'exact_latest differs from allowed latest tag'); assert.equal(found.tags.includes('latest'),true); assert.equal(found.integrity,row.integrity);} else if(row.status==='compatibility_exception') validateException(row,registry);}
  for(const retry of r.retry_history){keys(retry,['snapshot_id','t0','declaration_set_digest'],'retry'); assert.equal(retry.snapshot_id,r.snapshot_id,'mixed snapshot retry'); assert.equal(retry.t0,r.t0,'second cutoff in snapshot family');}
  return new Map(r.declarations.map(row=>[composite(row),row]));
}

async function reconstructDeclarations(){const rows=[]; for(const [manifest,key] of Object.entries(MANIFEST_KEYS)){const value=await json(key); for(const section of ['dependencies','devDependencies']) for(const [name,version] of Object.entries(value[section]??{})){if(String(version).startsWith('workspace:')){assert.ok(WORKSPACE_PACKAGES.has(name),'unexpected workspace reference'); continue;} const map=MANIFEST_CONTEXT[manifest]; const context=typeof map==='string'?map:map[section]; rows.push({manifest_path:manifest,dependency_section:section,package_name:name,context,version});}} return rows;}
async function validateRows(resolutionRows){const reconstructed=await reconstructDeclarations(); const ids=reconstructed.map(composite); assert.equal(new Set(ids).size,ids.length); assert.deepEqual(new Set(ids),new Set(resolutionRows.keys()),'missing/extra/wrong-context declaration row'); for(const row of reconstructed){const selected=resolutionRows.get(composite(row)); assert.equal(row.version,selected.selected_version,`manifest pin mismatch: ${composite(row)}`); assert.ok(exact(row.version));}}

function groupRow(rows,context,name){return [...rows.values()].find(r=>r.context===context&&r.package_name===name);}
function validateReactGroups(rows){for(const ctx of ['storefront-runtime','api-tooling']) assert.equal(groupRow(rows,ctx,'react').selected_version,groupRow(rows,ctx,'react-dom').selected_version,`${ctx} React pair mismatch`); assert.notEqual(groupRow(rows,'storefront-runtime','react').selected_version,groupRow(rows,'api-tooling','react').selected_version,'API/storefront React contexts conflated');}
function validateNonSwcGroups(rows){assert.match(groupRow(rows,'storefront-runtime','next').selected_version,/^16\./,'Next 16 is mandatory'); validateReactGroups(rows); const medusa=[...rows.values()].filter(r=>r.package_name.startsWith('@medusajs/')).map(r=>r.selected_version); assert.equal(new Set(medusa).size,1,'Medusa family mismatch'); assert.equal(groupRow(rows,'root-tooling','turbo').selected_version,groupRow(rows,'shared-eslint-tooling','eslint-plugin-turbo').selected_version,'Turbo group mismatch');}
function validateSwcPublishedCompatibility(resolution,registry,registryBytes,rows){
  const coreKey='apps/api/package.json + devDependencies + @swc/core + api-tooling';
  const jestKey='apps/api/package.json + devDependencies + @swc/jest + api-tooling';
  const core=rows.get(coreKey),jest=rows.get(jestKey);
  assert.ok(core&&jest,'missing exact API-tooling SWC declaration rows');
  assert.equal(composite(core),coreKey); assert.equal(composite(jest),jestKey);
  assert.ok(resolution.declarations.includes(core)&&resolution.declarations.includes(jest),'SWC rows must belong to the sealed resolution envelope');
  assert.equal(resolution.snapshot_id,SEALED_SNAPSHOT); assert.equal(resolution.t0,SEALED_T0); assert.equal(registry.header.t0,SEALED_T0);
  assert.equal(resolution.registry_snapshot_sha256,`sha256:${sha(registryBytes)}`,'sealed registry bytes drift');
  for(const [row,expected] of [[core,'1.15.47'],[jest,'0.2.39']]){const {record,found}=versionRecord(registry,row.package_name,row.selected_version); assert.equal(row.selected_version,expected); assert.equal(record.dist_tags.latest,expected); assert.equal(row.integrity,found.integrity);}
  const jestVersion=versionRecord(registry,'@swc/jest','0.2.39').found;
  assert.equal(jestVersion.peers?.['@swc/core'],'*','missing or unsupported sealed @swc/jest peer proof');
}
