function classifyPnpmAudit(stdoutBytes,exitCode){
  assert.ok([0,1].includes(exitCode),`unrecognized pnpm audit exit ${exitCode}`);
  assert.ok(stdoutBytes?.length,'pnpm audit JSON is missing');
  let report; try{report=JSON.parse(stdoutBytes)}catch(error){assert.fail(`pnpm audit output must be valid JSON: ${error.message}`)}
  exactKeys(report,['advisories','metadata'],'pnpm 11.18.0 audit report');
  const advisories=obj(report.advisories,'audit advisories'),metadata=obj(report.metadata,'audit metadata');
  exactKeys(metadata,['vulnerabilities','dependencies','devDependencies','optionalDependencies','totalDependencies'],'audit metadata');
  const vulnerabilities=obj(metadata.vulnerabilities,'audit vulnerability counts');
  exactKeys(vulnerabilities,['info','low','moderate','high','critical'],'audit vulnerability counts');
  for(const [name,count] of Object.entries(vulnerabilities)) assert.ok(Number.isInteger(count)&&count>=0,`invalid ${name} vulnerability count`);
  for(const name of ['dependencies','devDependencies','optionalDependencies','totalDependencies']) assert.ok(Number.isInteger(metadata[name])&&metadata[name]>=0,`invalid audit metadata ${name}`);
  for(const [id,advisory] of Object.entries(advisories)){
    assert.match(id,/^\d+$/,'audit advisory id must be numeric');
    const required=['findings','id','title','module_name','vulnerable_versions','severity','cwe','github_advisory_id','url'],allowed=[...required,'patched_versions'];
    keys(advisory,required,`audit advisory ${id}`); assert.ok(Object.keys(advisory).every(key=>allowed.includes(key)),`audit advisory ${id} has unknown keys`);
    assert.equal(advisory.id,Number(id)); assert.equal(typeof advisory.title,'string'); assert.equal(typeof advisory.module_name,'string'); assert.equal(typeof advisory.vulnerable_versions,'string'); assert.equal(typeof advisory.cwe,'string'); assert.equal(typeof advisory.github_advisory_id,'string'); assert.equal(typeof advisory.url,'string'); if('patched_versions' in advisory) assert.equal(typeof advisory.patched_versions,'string');
    assert.ok(['low','moderate','high','critical'].includes(advisory.severity),`audit advisory ${id} is below default low threshold or unknown`);
    assert.ok(Array.isArray(advisory.findings),`audit advisory ${id} findings must be an array`);
    for(const finding of advisory.findings){exactKeys(finding,['version','paths','dev','optional','bundled'],`audit advisory ${id} finding`); assert.equal(typeof finding.version,'string'); assert.ok(Array.isArray(finding.paths)&&finding.paths.every(path=>typeof path==='string')); for(const flag of ['dev','optional','bundled']) assert.equal(typeof finding[flag],'boolean');}
  }
  const advisoryCount=Object.keys(advisories).length;
  assert.equal(exitCode,advisoryCount>0?1:0,'pnpm 11.18.0 JSON audit exit must equal filtered advisory presence');
  return {classification:advisoryCount>0?'vulnerability_report':'clean_report',advisory_count:advisoryCount,terminal:false};
}
